from __future__ import annotations

import asyncio
import logging
from typing import Any

from rca_pipeline.config import RunConfig
from rca_pipeline.taxonomy import taxonomy_to_rich_prompt
from rca_pipeline.llm_client import process_batches_async

logger = logging.getLogger(__name__)

MODULE_NAME = "scopus_l1"


def _build_system_prompt(taxonomy_prompt: str) -> str:
    _BEFORE = """You are an expert classifier for Elsevier support tickets.
Your task: Classify why the customer contacted Scopus support into exactly one of 16 Level 1 categories. Each category carries a Definition. The ticket text starts with the ticket Subject, then the conversation. Assign the single best-fitting LEAF code (e.g. SCLV3.1). Apply these decision rules: [Primary test — can the customer access Scopus?] First question for every ticket: is the customer currently unable to log in to, or use, Scopus or its content/features (including Scopus AI)? Only if yes is the ticket a candidate for Access. The original Oracle 'Access' tag is not evidence; classification is based on the conversation (and, when the customer text is empty, the subject and agent text). [Rule 1 — can log in, wants a change] Customer can already sign in and only asks for an update or change (change email, merge/delete accounts, fix name/affiliation, add or correct documents, link ORCID, institution logo/reports) is NOT Access. Classify by the actual request (Account Management, Author Profile Correction, ORCID Issue, Institution Admin / Support, etc.). [Rule 2 — cannot log in, wants a change to regain access] Customer cannot log in or access Scopus and asks support to change something on the account/profile/institution so they can get in (change linked email, restore a deleted account, merge accounts, add IP/entitlement, grant user access) is Access. The access blocker decides the category, not the fix requested. [Rules applied to every category] Rules 1 and 2 were applied uniformly to all categories, in both directions: tickets tagged Access that are really change requests were moved out; tickets that look like account/profile/admin requests but describe an inability to sign in or access were moved into Access. [IP and IPW requests] IP additions and IPW (institutional profile/access setup) requests are Access when the purpose is to let users get in or restore access. Routine institution housekeeping (profile data, SSO/SAML setup, usage, branding) with no access blocker goes to Institution Admin / Support. This is the main judgement area and could shift the Access count. [Access vs Performance & Functionality Issues] Error pages (404, 'Something went wrong') that stop sign-in or entry are Access. Errors, bugs or slowness when the customer can otherwise use Scopus (search, export, display) are Performance & Functionality Issues. [Wrong-profile login] Customer can log in but lands on someone else's profile/account: classified Access (login/authentication problem), root cause 'Wrong account / unexpected account switching'. [Registration and new accounts] Registration or account creation that fails or is blocked, where the goal is to get into Scopus, is Access (root cause 'Registration failed'). A plain how-to / information request on registering, with no blocker, is Account Management; SME scenario 'Customer asked how to register' still maps to Registration failed when the ticket is tagged Access. [Profile views with limited access] Profile or documents visible only in Scopus Preview, 'Check access' or limited view is Access. Profile content errors seen by a user with full access (missing/wrong documents, name, affiliation) are Author Profile Correction. [Primary issue wins] If a conversation has several issues, classify by the first/primary issue that prompted the customer to contact support, not by incidental words in the thread. [Empty customer text / chat transcript only] When the customer text is empty (for example a forwarded chat transcript), use the subject and the agent text. If the subject or agent text points to a sign-in or access problem the ticket stays Access with root cause 'Unknown rootcause'; if no issue can be seen at all it is Unclear / No Query. REVISED TAXONOMY OVERRIDES - these take precedence over the rules above. (1) The Account Management category no longer exists. Wherever a rule above says Account Management, use Access for account changes (change or correct the account email, account name or details, duplicate or multiple accounts, merging accounts, closing or deleting the account, registration or account-setup guidance, registered-email lookup or account status, password or security-settings questions), even when the customer can sign in, and use Data / Privacy Request for requests about personal data (what is held, a copy, or removal on privacy grounds). (2) Rule 1 still applies to everything else: a customer who can sign in and wants an author profile, ORCID, content, metrics or institution change is classified by that request, not as Access. (3) Scopus AI Access takes precedence over Access whenever the access problem is specifically about Scopus AI.

## Taxonomy
"""
    _AFTER = """

## Instructions
1. Assign the single leaf-level code (e.g. SCLV3.1) for the Level 1 category that best matches this ticket. Read each category Definition and the decision rules, and match on what the ticket shows, not on surface keywords. Only use codes from the taxonomy. Always return exactly one code from the taxonomy; never leave the code empty. → `scl1_code`
2. In one or two sentences, explain why this Level 1 category applies and why the closest alternative does not. Refer to what the ticket actually shows. Do not use apostrophes or quotation marks in your answer. → `scl1_justification`
3. Copy verbatim the single sentence or phrase from the transcript that most strongly supports this Level 1 category. Do not paraphrase, infer, or add words that are not in the transcript. If no direct evidence exists, return an empty string. → `scl1_evidence`

## Output Format
Return a JSON array — one object per record:
[
  {
    "uid": "<record uid>",
    "scl1_code": "<SCLV_code>",
    "scl1_justification": "<string>",
    "scl1_evidence": "<string>"
  }
]

IMPORTANT: Return ONLY valid JSON. No markdown fences. Every input uid MUST appear in output.
CRITICAL: Always use LEAF-level codes (with a dot, e.g. CR4.1), NEVER L1 group codes (e.g. CR4)."""
    return _BEFORE + taxonomy_prompt + _AFTER


_USER_PROMPT_TEMPLATE = """Classify the following support transcripts.

{records_json}

Return a JSON array with one object per record.
Each object must have: uid, scl1_code, scl1_justification, scl1_evidence"""





async def classify_scopus_l1(
    batches: list[list[dict[str, str]]],
    taxonomies: dict[str, dict],
    cfg: RunConfig,
) -> list[dict[str, Any]]:
    """Run scopus_l1 classification on all batches."""
    tax = taxonomies.get("scopus_l1", {})
    tax_prompt = taxonomy_to_rich_prompt(tax, "SCLV")
    system_prompt = _build_system_prompt(tax_prompt)

    results = await process_batches_async(
        batches,
        system_prompt,
        _USER_PROMPT_TEMPLATE,
        cfg,
        
    )

    logger.info("scopus_l1: classified %d records", len(results))
    return results


def run(batches, taxonomies, cfg):
    """Synchronous wrapper."""
    return asyncio.run(classify_scopus_l1(batches, taxonomies, cfg))
